    const operators = db.prepare(`
      SELECT * FROM operators
      WHERE callsign LIKE ? OR UPPER(name) LIKE ? OR UPPER(qth) LIKE ?
      ORDER BY callsign LIMIT 50
    `).all(pattern, pattern, pattern);
