    const ep = r.ep_abbr ? ` ${r.ep_abbr}` : '';
    text += `    ${r.callsign.padEnd(10)} ${r.repeater_name.padEnd(20)} ${rapport}${ep}\n`;
  }

  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
