  text += '='.repeat(60) + '\n\n';

  let currentBl = '';
  let currentBz = '';
  for (const r of reports) {
    if (r.bundesland_name !== currentBl) {
      currentBl = r.bundesland_name || 'Sonstige';
      text += `\n── ${currentBl} ──\n`;
      currentBz = '';
    }
    if (r.bezirk_code !== currentBz) {
      currentBz = r.bezirk_code || '??';
