  try {
    const result = db.prepare('INSERT INTO exercises (date) VALUES (?)').run(date);
    const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(result.lastInsertRowid);
    res.status(201).json(exercise);

